System.out.println("=== Uzytkownicy z co najmniej 1 zamowieniem ===");
print(stmt.executeQuery("""
    SELECT u.name FROM users u
    WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id)
    ORDER BY u.name
    """));
// EXISTS sprawdza, czy podzapytanie zwrocilo CHOC JEDEN wiersz - to
// zwykle NAJSZYBSZY sposob na sprawdzenie istnienia powiazanego rekordu.

System.out.println("\n=== Uzytkownicy BEZ zamowien ===");
print(stmt.executeQuery("""
    SELECT u.name FROM users u
    WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id)
    """));
// NOT EXISTS - odwrotnosc, znajduje wiersze BEZ dopasowania.

System.out.println("=== Srednia liczba zamowien na uzytkownika ===");
print(stmt.executeQuery("""
    SELECT AVG(zamowienia_na_uzytkownika.ile) AS srednia
    FROM (
        SELECT u.id, COUNT(o.id) AS ile
        FROM users u
        LEFT JOIN orders o ON o.user_id = u.id
        GROUP BY u.id
    ) AS zamowienia_na_uzytkownika
    """));
// LEFT JOIN w podzapytaniu jest kluczowy - dzieki niemu uzytkownik
// z 0 zamowien TEZ wchodzi do sredniej jako 0, a nie jest pominiety.

System.out.println("=== Liczba zamowien kazdego usera ===");
print(stmt.executeQuery("""
    SELECT
        u.name,
        (SELECT COUNT(*) FROM orders o WHERE o.user_id = u.id) AS liczba_zamowien
    FROM users u
    ORDER BY u.name
    """));
// Podzapytanie odwoluje sie do u.id z zapytania ZEWNETRZNEGO - to jest
// wlasnie korelacja. Musi zwrocic dokladnie 1 wiersz i 1 kolumne.
